244	/**
245	 * When `target.doc_type:"mbs"` is set on a sch_* tool, the run_shell mode
246	 * (which drives both BuildModeInitCode + ModeToFrameType in terminal_frame.cpp)
247	 * gets switched from "sch" to "mbs". This makes:
248	 *   - The bootstrap bind `mbs = kicad.get_mbs_schematic()` directly
249	 *   - The agent diff-view transactions route to FRAME_MBSCH (so changes
250	 *     pop up in the MBS editor's diff overlay, not the SCH one)
251	 * The target preamble for this case just aliases `sch = mbs` so unmodified
252	 * sch_* scripts keep working without rewriting to use `mbs`.
253	 *
254	 * Returns the run_shell mode the rest of the pipeline should treat the
255	 * tool as. Returns the original app when no MBS routing applies.
256	 */
257	static std::string effectiveRunShellMode( const std::string& aApp,
258	                                          const nlohmann::json& aInput )
259	{
260	    if( aApp != "sch" )
261	        return aApp;
262	
263	    if( !aInput.is_object() || !aInput.contains( "target" ) )
264	        return aApp;
265	
266	    const auto& target = aInput["target"];
267	
268	    if( !target.is_object() )
269	        return aApp;
270	
271	    if( target.value( "doc_type", "" ) == "mbs" )
272	        return "mbs";
273	
274	    return aApp;
275	}
