293	void KICAD_API_SERVER::onApiRequest( std::string* aRequest, KINNG_REQUEST_SERVER* aServer )
294	{
295	    wxLogTrace( traceApi, wxString::Format( "Server: onApiRequest from %s",
296	                                            aServer == m_execServer.get() ? "exec" : "primary" ) );
297	
298	    if( !m_readyToReply )
299	    {
300	        ApiResponse notHandled;
301	        notHandled.mutable_status()->set_status( ApiStatusCode::AS_NOT_READY );
302	        notHandled.mutable_status()->set_error_message( "KiCad is not ready to reply" );
303	        aServer->Reply( notHandled.SerializeAsString() );
304	        log( "Got incoming request but was not yet ready to reply." );
305	        // Note: Do NOT delete aRequest - it's managed by KINNG internally
306	        return;
307	    }
308	
309	    // Assign a unique ID to this request for tracking
310	    uint64_t requestId = m_nextRequestId.fetch_add( 1 );
311	
312	    // Queue the request for processing during idle time
313	    // This avoids processing during ProcessPendingEvents() which causes issues on macOS
314	    {
315	        std::lock_guard<std::mutex> queueLock( m_queueMutex );
316	        m_pendingRequests[requestId] = PENDING_REQUEST( requestId, *aRequest, aServer );
317	        m_requestQueue.push( requestId );
318	        m_hasQueuedRequests.store( true );
319	    }
320	
321	    // Note: Do NOT delete aRequest - it's managed by KINNG internally
322	
323	    // Wake the main thread's event loop to process the request during idle time
324	    wxWakeUpIdle();
325	
326	    // Schedule a fallback timer on the main thread to process the request.
327	    // On macOS, wxEVT_IDLE may not fire reliably when other timers are active
328	    // (e.g., the agent frame's 50ms streaming update timer). CallAfter is thread-safe
329	    // and schedules the timer start on the main thread.
330	    if( wxTheApp )
331	    {
332	        wxTheApp->CallAfter( [this]()
333	        {
334	            if( m_hasQueuedRequests.load() && !m_pollTimer.IsRunning() )
335	                m_pollTimer.StartOnce( 50 );
336	        } );
337	    }
338	
339	    // Wait for THIS request's reply to be ready (each request waits for its own reply)
340	    std::string replyString;
341	    {
342	        std::unique_lock<std::mutex> lock( m_replyMutex );
343	
344	        // Wait until our specific request has its reply ready
345	        m_replyReady.wait( lock, [this, requestId]()
346	        {
347	            std::lock_guard<std::mutex> queueLock( m_queueMutex );
348	            auto it = m_pendingRequests.find( requestId );
349	            return it == m_pendingRequests.end() || it->second.replyReady;
350	        } );
351	
352	        // Retrieve and remove our reply
353	        {
354	            std::lock_guard<std::mutex> queueLock( m_queueMutex );
355	            auto it = m_pendingRequests.find( requestId );
356	            if( it != m_pendingRequests.end() )
357	            {
358	                replyString = std::move( it->second.reply );
359	                m_pendingRequests.erase( it );
360	            }
361	        }
362	    }
363	
364	    // Send the reply back via the originating server
365	    aServer->Reply( replyString );
366	}
