388	void KICAD_API_SERVER::processNextQueuedRequest()
389	{
390	    // Check if we have any queued requests to process
391	    if( !m_hasQueuedRequests.load() )
392	        return;
393	
394	    uint64_t requestId = 0;
395	    std::string requestString;
396	
397	    // Get one request from the queue
398	    {
399	        std::lock_guard<std::mutex> lock( m_queueMutex );
400	        if( m_requestQueue.empty() )
401	        {
402	            m_hasQueuedRequests.store( false );
403	            return;
404	        }
405	
406	        requestId = m_requestQueue.front();
407	        m_requestQueue.pop();
408	
409	        auto it = m_pendingRequests.find( requestId );
410	        if( it == m_pendingRequests.end() )
411	        {
412	            // Request was somehow removed, skip it
413	            if( m_requestQueue.empty() )
414	                m_hasQueuedRequests.store( false );
415	            return;
416	        }
417	
418	        requestString = it->second.request;
419	
420	        if( m_requestQueue.empty() )
421	            m_hasQueuedRequests.store( false );
422	    }
423	
424	    // Process the request and store the reply
425	    processApiRequest( requestId, requestString );
426	}
