459	            if( ADVANCED_CFG::GetCfg().m_EnableAPILogging )
460	                log( "Response (ERROR): " + error.Utf8DebugString() );
461	        }
462	        else
463	        {
464	            API_RESULT result;
465	
466	            // Parse type name for logging
467	            std::string requestTypeName = "<unparseable>";
