241	bool PYTHON_EXEC_THREAD::InterruptPython()
242	{
243	    unsigned long threadId = m_pythonThreadId.load();
244	
245	    if( threadId == 0 )
246	    {
247	        wxLogInfo( "HEADLESS_EXEC: InterruptPython called but no Python thread ID — "
248	                   "thread may not have started yet" );
249	        return false;
250	    }
251	
252	    wxLogInfo( "HEADLESS_EXEC: InterruptPython — setting stop flag for thread %lu", threadId );
253	
254	    // We intentionally do NOT call PyThreadState_SetAsyncExc here.
255	    // That function requires the GIL, but acquiring the GIL from the main thread
256	    // can deadlock: the Python thread may be blocked in an IPC call waiting for
257	    // the main thread to process it via wxYield, while the main thread blocks
258	    // waiting for the GIL.
259	    //
260	    // Instead, we set m_stopRequested so the thread knows it was cancelled.
261	    // The Python thread will finish its current operation naturally.
262	    // The caller (CancelExecution) handles force-completing the execution state
263	    // so the app doesn't hang waiting for the thread.
264	    m_stopRequested.store( true );
265	
266	    wxLogInfo( "HEADLESS_EXEC: InterruptPython — stop requested" );
