void KICAD_API_SERVER::ProcessPendingRequests()
{
    // Diagnostic: log entry + how many requests are queued. Helps confirm
    // whether spin-loop callers are actually draining the queue or whether
    // the queue is empty (in which case the bug is upstream — e.g. NNG dial
    // blocking before the server even sees the request).
    bool hadQueued = m_hasQueuedRequests.load();
    size_t queueSize = 0;
    {
        std::lock_guard<std::mutex> lock( m_queueMutex );
        queueSize = m_requestQueue.size();
    }

    if( hadQueued || queueSize > 0 )
    {
        wxLogMessage( "API_SERVER[%p]: ProcessPendingRequests entry, hasQueued=%d, queueSize=%zu",
                      this, hadQueued, queueSize );
    }

    int drained = 0;
    while( m_hasQueuedRequests.load() )
    {
        processNextQueuedRequest();
        drained++;
    }

    if( drained > 0 )
    {
        wxLogMessage( "API_SERVER[%p]: ProcessPendingRequests drained %d request(s)",
                      this, drained );
    }
}

