1625	void AGENT_FRAME::OnSend( wxCommandEvent& aEvent )
1626	{
1627	    try
1628	    {
1629	    wxLogInfo( "AGENT_FRAME::OnSend called" );
1630	    // NOTE: This method still uses legacy code because it handles KiCad-specific requirements
1631	    // (authentication, pending editor state, system prompt with schematic/PCB context, KIWAY
1632	    // target sheet reset) that the controller doesn't currently support.
1633	    // System prompt is now handled server-side.
1634	
1635	    // Hide plan approval button when user sends a new message
1636	    m_bridge->PushRemovePlanApproval();
1637	
1638	    // If already generating: queue, cancel+send, or stop depending on context
1639	    if( m_isGenerating )
1640	    {
1641	        bool hasContent = !m_pendingInputText.IsEmpty() || !m_pendingAttachments.empty();
1642	
1643	        if( !hasContent )
1644	        {
1645	            // Empty input → stop (also clears queue)
1646	            ClearQueuedMessage();
1647	            OnStop( aEvent );
1648	            return;
1649	        }
1650	
1651	        // Streaming / tool execution: queue the message.
1652	        QueueMessage();
1653	        return;
1654	    }
1655	
1656	    // Auto-reject pending open/close editor request if user sends a new message.
1657	    // This runs outside m_isGenerating because OnChatToolStart calls
1658	    // StopGeneratingAnimation() which sets m_isGenerating = false.
1659	    bool hasApproval = m_pendingOpenSch || m_pendingOpenPcb;
1660	
1661	    if( hasApproval )
1662	    {
1663	        ClearQueuedMessage();
1664	        DoCancelOperation( false );
1665	        // m_pendingInputText still has the user's text — fall through to normal send.
1666	    }
1667	
1668	    // Check authentication first
1669	    if( !CheckAuthentication() )
1670	    {
1671	        AppendHtml( "<p><i>Please sign in to continue.</i></p>" );
1672	        return;
1673	    }
1674	
1675	    wxString text = m_pendingInputText;
1676	    m_pendingInputText.Clear();
1677	    if( text.IsEmpty() && m_pendingAttachments.empty() )
1678	        return;
1679	
1680	    // Save for retry on error
1681	    m_lastSentText = text;
1682	
1683	    // Reset scroll state for new user message - user sending indicates engagement at bottom
1684	    m_userScrolledUp = false;
1685	
1686	    // Clear onboarding content when user sends first message
1687	    if( m_showingOnboarding )
1688	    {
1689	        m_fullHtmlContent.Clear();
1690	        m_showingOnboarding = false;
1691	    }
1692	
1693	    // Build user message HTML
1694	    wxString escapedText = text;
1695	    escapedText.Replace( "&", "&amp;" );
1696	    escapedText.Replace( "<", "&lt;" );
1697	    escapedText.Replace( ">", "&gt;" );
1698	    escapedText.Replace( "\n", "<br>" );
1699	
1700	    wxString bubbleContent = FileAttach::BuildAttachmentBubbleHtml( m_pendingAttachments )
1701	                             + escapedText;
1702	    wxString msgHtml = wxString::Format(
1703	        "<div class=\"user-msg-row my-3\"><div class=\"user-msg py-2 px-3.5 whitespace-pre-wrap break-words\">%s</div></div>",
1704	        bubbleContent );
1705	
1706	    // Add streaming content container for incremental updates
1707	    wxString streamingDiv = wxS( "<div id=\"streaming-content\"></div>" );
1708	
1709	    // Append to internal HTML state
1710	    m_fullHtmlContent += msgHtml + streamingDiv;
1711	
1712	    // Save HTML snapshot for markdown re-rendering during streaming
1713	    m_htmlBeforeAgentResponse = m_fullHtmlContent;
1714	
1715	    // Full page re-render
1716	    SetHtml( m_fullHtmlContent );
1717	
1718	    // Clear Input and Update UI
1719	    m_bridge->PushInputClear();
1720	    m_bridge->PushInputFocus();
1721	    m_bridge->PushActionButtonState( "Stop" );
1722	
1723	    // Reset frame streaming state
1724	    m_currentResponse = "";
1725	    m_toolCallHtml = "";
1726	    m_thinkingHtml = "";
1727	    m_thinkingContent = "";
1728	    m_thinkingExpanded = false;
1729	    m_thinkingHtmlDirty = false;
1730	    m_isThinking = false;
1731	    m_pendingToolCalls = nlohmann::json::array();
1732	    // NOTE: Don't reset m_toolResultCounter here - old tool-result-N IDs persist in
1733	    // m_fullHtmlContent after SetHtml(). Counter must be monotonically increasing to
1734	    // avoid duplicate DOM IDs. Only reset in DoNewChat/OnChatHistoryLoaded (full re-render).
1735	    m_runningHtmlByIdx.clear();
1736	    m_activeToolResultIdx = -1;
1737	    m_stopRequested = false;
1738	    m_userScrolledUp = false;
1739	    m_htmlUpdatePending = false;
1740	
1741	    // ── Claude Code backend ──────────────────────────────────────────────
1742	    if( m_backend == AgentBackend::CLAUDE_CODE )
1743	    {
1744	        if( m_ccController )
1745	        {
1746	            // Clear stale response before UI renders — otherwise the html update timer
1747	            // can flash the previous turn's text in the new streaming div.
1748	            m_ccController->ClearCurrentResponse();
1749	
1750	            // Sync frame history into CC controller so it includes prior messages
1751	            // (from either backend) before appending the new user message
1752	            m_ccController->SetChatHistory( m_chatHistory );
1753	
1754	            StartGeneratingAnimation();
1755	
1756	            if( !m_ccController->SendMessage( text.ToStdString() ) )
1757	            {
1758	                wxLogWarning( "AGENT_FRAME: CC subprocess not running, restarting" );
1759	                StopGeneratingAnimation();
1760	
1761	                // Restart the subprocess — resume if we have a session ID, else new
1762	                std::string sessionId = m_ccController->GetSessionId();
1763	
1764	                if( !sessionId.empty() )
1765	                    m_ccController->ResumeSession( sessionId );
1766	                else
1767	                    m_ccController->NewSession();
1768	
1769	                m_ccController->SetChatHistory( m_chatHistory );
1770	                StartGeneratingAnimation();
1771	
1772	                if( !m_ccController->SendMessage( text.ToStdString() ) )
1773	                {
1774	                    wxLogError( "AGENT_FRAME: CC subprocess restart failed" );
1775	                    StopGeneratingAnimation();
1776	                    m_pendingAttachments.clear();
1777	                    return;
1778	                }
1779	            }
1780	
1781	            // Sync and save after user message is recorded
1782	            m_chatHistory = m_ccController->GetChatHistory();
1783	            m_chatHistoryDb.Save( m_chatHistory );
1784	            USAGE_SYNC::Instance()->TrackEvent( "agent.message.sent", "agent" );
1785	
1786	            // Generate title on first message (same as Zeo agent path)
1787	            if( m_chatHistoryDb.GetTitle().empty() && m_chatController )
1788	                m_chatController->RequestTitle( text.ToStdString() );
1789	        }
1790	
1791	        m_pendingAttachments.clear();
1792	        return;
1793	    }
1794	
1795	    // ── Zeo Agent backend ────────────────────────────────────────────────
1796	
1797	    // Configure controller for this request (system prompt now handled server-side)
1798	    if( m_chatController )
1799	    {
1800	        // Sync frame's history to controller before repair
1801	        // (controller may be out of sync if conversation was loaded from disk)
1802	        m_chatController->SetHistory( m_chatHistory );
1803	
1804	        // Repair orphaned tool_use/tool_result blocks
1805	        m_chatController->RepairHistory();
1806	
1807	        // Sync repaired history back to frame for rendering/persistence
1808	        m_chatHistory = m_chatController->GetChatHistory();
1809	        m_apiContext = m_chatController->GetApiContext();
1810	    }
1811	
1812	    // Transition frame's state machine (legacy - controller also has state machine)
1813	    m_conversationCtx.Reset();
1814	    m_conversationCtx.TransitionTo( AgentConversationState::WAITING_FOR_LLM );
1815	
1816	    // Configure LLM client with selected model
1817	    m_llmClient->SetModel( m_currentModel );
1818	
1819	    // Sync agent target sheet with the user's current sheet on first message,
1820	    // reset on subsequent messages so the agent can navigate freely
1821	    {
1822	        bool isFirstMessage = m_chatHistory.empty()
1823	                              || std::none_of( m_chatHistory.begin(), m_chatHistory.end(),
1824	                                               []( const nlohmann::json& msg )
1825	                                               {
1826	                                                   return msg.value( "role", "" ) == "user";
1827	                                               } );
1828	
1829	        if( isFirstMessage )
1830	        {
1831	            // Query the user's current sheet from the schematic editor and set it as target
1832	            try
1833	            {
1834	                std::string resp = SendRequest( FRAME_SCH, "get_sch_sheets" );
1835	                if( !resp.empty() )
1836	                {
1837	                    auto respJson = nlohmann::json::parse( resp, nullptr, false );
1838	                    if( !respJson.is_discarded() && respJson.contains( "current_sheet_uuid" ) )
1839	                    {
1840	                        nlohmann::json payload;
1841	                        payload["sheet_uuid"] = respJson["current_sheet_uuid"];
