152	bool AGENT_AUTH::IsAuthenticated()
153	{
154	    std::lock_guard<std::recursive_mutex> lock( m_tokenMutex );
155	
156	    if( m_accessToken.empty() )
157	        return false;
158	
159	    if( IsTokenExpired() )
160	    {
161	        // Try to proactively refresh (we're within the 5-min buffer)
162	        if( !RefreshToken() )
163	        {
164	            // Refresh failed, but if the token hasn't actually expired yet,
165	            // it's still valid at the server — don't block the user
166	            return !IsTokenHardExpired();
167	        }
168	    }
169	
170	    return true;
171	}
