/*
 * Copyright (C) 2026, Zeo <team@zeo.dev>
 */

// Console-mode launcher for the Zeo MCP server on Windows.
//
// Embeds the same python311.dll that Zeo.exe links against, points PYTHONHOME
// at bin/ (where Lib/ already lives for the GUI's scripting console), and
// hands off to kipy.mcp.server.run.
//
// Registered with Claude Code via:
//   claude mcp add zeo -s user -- "C:\Program Files\Zeo\bin\zeo-mcp.exe"

#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <windows.h>
#include <filesystem>

namespace fs = std::filesystem;

int wmain()
{
    wchar_t exePath[MAX_PATH];
    GetModuleFileNameW( nullptr, exePath, MAX_PATH );
    fs::path binDir = fs::path( exePath ).parent_path();

    PyConfig config;
    PyConfig_InitIsolatedConfig( &config );
    config.use_environment = 0;
    config.parse_argv = 0;

    PyConfig_SetString( &config, &config.home, binDir.wstring().c_str() );

    config.module_search_paths_set = 1;
    auto lib  = ( binDir / L"Lib" ).wstring();
    auto site = ( binDir / L"Lib" / L"site-packages" ).wstring();
    auto dlls = ( binDir / L"DLLs" ).wstring();  // C extension modules (_socket.pyd, _asyncio.pyd, …)
    PyWideStringList_Append( &config.module_search_paths, lib.c_str() );
    PyWideStringList_Append( &config.module_search_paths, dlls.c_str() );
    PyWideStringList_Append( &config.module_search_paths, site.c_str() );

    PyStatus s = Py_InitializeFromConfig( &config );
    PyConfig_Clear( &config );
    if( PyStatus_Exception( s ) )
    {
        Py_ExitStatusException( s );
        return 1;
    }

    int rc = PyRun_SimpleString(
        "import asyncio\n"
        "from kipy.mcp.server import run\n"
        "asyncio.run(run())\n"
    );

    Py_Finalize();
    return rc;
}

        Log "Bundled JRE already present."
    }
} else {
    Log "Warning: Freerouting JAR not found, skipping."
}

# --- Phase 3: Install kipy ---

Write-Host ""
Write-Host "=========================================="
Write-Host "PHASE 3: Installing kipy"
Write-Host "=========================================="

$sitePackages = "$InstallDir\bin\Lib\site-packages"

function Install-Kipy {
    Log "Installing kipy (KiCad Python bindings)..."

    $kipySource = "$KicadPythonDir\kipy"
    $protoInput = "$KicadSourceDir\api\proto"

    # Generate protobuf Python files
    if (-not (Test-Path "$kipySource\proto\common\envelope_pb2.py")) {
        Log "Generating protobuf Python files..."
        $protoFiles = Get-ChildItem -Path $protoInput -Filter "*.proto" -Recurse | Select-Object -ExpandProperty FullName
        & $Protoc --python_out="$kipySource\proto" --proto_path=$protoInput @protoFiles
        python -m protoletariat --dont-create-package --in-place --exclude-google-imports --python-out "$kipySource\proto" protoc --protoc-path $Protoc --proto-path $protoInput @protoFiles
    }

    # Copy kipy package
    if (Test-Path "$sitePackages\kipy") {
        Remove-Item -Recurse -Force "$sitePackages\kipy"
    }
    New-Item -ItemType Directory -Path $sitePackages -Force | Out-Null
    Copy-Item -Recurse $kipySource "$sitePackages\kipy"

    # Install Python dependencies if missing
    if (-not (Test-Path "$sitePackages\google\protobuf")) {
        Log "Installing Python dependencies..."
        python -m pip install --no-user --target $sitePackages "protobuf>=6.33" "pynng>=0.8.0,<0.9.0" typing_extensions matplotlib cairosvg 2>&1 | Out-Null
    }

    Log "kipy installed."
}

if (Test-Path $KicadPythonDir) {
    Install-Kipy
} else {
    Log "kipy source not found at $KicadPythonDir, skipping."
}

# --- Phase 4: Create NSIS Installer ---

Write-Host ""
Write-Host "=========================================="
Write-Host "PHASE 4: Creating NSIS Installer"
Write-Host "=========================================="

# Find NSIS
$nsisExe = $null
$nsisSearchPaths = @(
    "$BuilderDir\.support\nsis-*\bin\makensis.exe",
    "C:\Program Files (x86)\NSIS\makensis.exe",
    "C:\Program Files\NSIS\makensis.exe"
)

foreach ($pattern in $nsisSearchPaths) {
    $found = Get-ChildItem $pattern -ErrorAction SilentlyContinue | Select-Object -First 1
    if ($found) {
        $nsisExe = $found.FullName
        break
    }
}

if (-not $nsisExe) {
    # Try PATH
    $nsisExe = Get-Command makensis.exe -ErrorAction SilentlyContinue | Select-Object -ExpandProperty Source
}

if (-not $nsisExe) {
    Log-Error "NSIS (makensis.exe) not found."
    Write-Host "  Install NSIS or run 'build.ps1 -Init' to download it."
    Write-Host ""
    Write-Host "  The output directory is ready at:"
    Write-Host "    $InstallDir"
    Write-Host ""
    Write-Host "  You can create the installer manually with build.ps1 -Package"
    exit 1
}

include_directories(
    ${PROJECT_SOURCE_DIR}/include
    ${PROJECT_SOURCE_DIR}/pcbnew
    ${BOOST_INCLUDE}
    ${CMAKE_CURRENT_SOURCE_DIR}
    ${CMAKE_BINARY_DIR}
    )

add_executable( test-nm-biu-to-ascii-mm-round-tripping
    EXCLUDE_FROM_ALL
    test-nm-biu-to-ascii-mm-round-tripping.cpp
    )

add_executable( utf8_tests
    EXCLUDE_FROM_ALL
    utf8_tests.cpp
    )
target_link_libraries( utf8_tests
    common
    ${wxWidgets_LIBRARIES}
    )

add_subdirectory( newstroke )

# Install zeo CLI tool (Python script — goes in SharedSupport, not MacOS, to avoid codesign issues)
if( APPLE )
    set( ZEO_CLI_BUILD_DIR "${OSX_BUNDLE_BUILD_DIR}/${OSX_BUNDLE_SUP_DIR}/bin" )

    add_custom_target( zeo_cli ALL
        COMMAND ${CMAKE_COMMAND} -E make_directory ${ZEO_CLI_BUILD_DIR}
        COMMAND ${CMAKE_COMMAND} -E copy
            ${CMAKE_CURRENT_SOURCE_DIR}/zeo
            ${ZEO_CLI_BUILD_DIR}/zeo
        COMMAND chmod +x ${ZEO_CLI_BUILD_DIR}/zeo
        COMMENT "Copying zeo CLI tool to app bundle"
        )

    install( PROGRAMS zeo
        DESTINATION ${OSX_BUNDLE_INSTALL_DIR}/${OSX_BUNDLE_SUP_DIR}/bin
        COMPONENT binary
        )
else()
    install( PROGRAMS zeo
        DESTINATION ${KICAD_BIN}
        COMPONENT binary
        )
endif()

# Native Windows MCP launcher. Embeds python311.dll (same one Zeo.exe links)
# and runs kipy.mcp.server from the bundled bin/Lib/site-packages. Replaces
# the bash zeo script for MCP integration on Windows, where bash isn't viable.
if( WIN32 )
    add_executable( zeo-mcp WIN32 zeo-mcp/zeo-mcp.cpp )

    target_include_directories( zeo-mcp PRIVATE ${PYTHON_INCLUDE_DIRS} )
    target_link_libraries( zeo-mcp PRIVATE ${PYTHON_LIBRARIES} )

    if( MSVC )
        # Override the WIN32 subsystem with CONSOLE for stdio MCP transport.
        # Mirrors the kicad-cli pattern in kicad/CMakeLists.txt.
        set_target_properties( zeo-mcp PROPERTIES COMPILE_DEFINITIONS_DEBUG          "_CONSOLE" )
        set_target_properties( zeo-mcp PROPERTIES COMPILE_DEFINITIONS_RELWITHDEBINFO "_CONSOLE" )
        set_target_properties( zeo-mcp PROPERTIES LINK_FLAGS_DEBUG          "/SUBSYSTEM:CONSOLE" )
        set_target_properties( zeo-mcp PROPERTIES LINK_FLAGS_RELWITHDEBINFO "/SUBSYSTEM:CONSOLE" )
        set_target_properties( zeo-mcp PROPERTIES LINK_FLAGS_RELEASE        "/SUBSYSTEM:CONSOLE" )
        set_target_properties( zeo-mcp PROPERTIES LINK_FLAGS_MINSIZEREL     "/SUBSYSTEM:CONSOLE" )
    endif()

    install( TARGETS zeo-mcp
        DESTINATION ${KICAD_BIN}
        COMPONENT binary
        )
endif()

