void LIBRARY_MANAGER::LoadGlobalTables( std::initializer_list<LIBRARY_TABLE_TYPE> aTablesToLoad )
{
    // Cancel any in-progress load
    {
        std::scoped_lock lock( m_adaptersMutex );

        for( const std::unique_ptr<LIBRARY_MANAGER_ADAPTER>& adapter : m_adapters | std::views::values )
            adapter->GlobalTablesChanged( aTablesToLoad );
    }

    // First-run init: seed the user's global lib tables from the bundled
    // templates if they don't exist yet. Without this step the user opens
    // Zeo on a fresh install, finds the symbol/footprint viewers empty,
    // and there's no UI path to recover (see fresh-Windows-install bug).
    // Mirrors upstream KiCad's "default" choice in DIALOG_GLOBAL_LIB_TABLE_CONFIG,
    // which Zeo no longer ships.
    seedGlobalTablesFromTemplates( aTablesToLoad );

    loadTables( PATHS::GetUserSettingsPath(), LIBRARY_TABLE_SCOPE::GLOBAL, aTablesToLoad );

