// If the destination already exists, decide whether to seed, repair,
// or leave alone. Three repairable cases:
//   (a) file missing entirely (fresh install)
//   (b) file exists but unparseable / empty (0.2.2 upgrade)
//   (c) file exists with a "KiCad" chained-table row whose absolute
//       URI no longer resolves (e.g. user ran the in-tree dev build,
//       then installed a DMG — the in-tree path got burned into the
//       chained row's URI but the in-tree bundle is gone). Rewrite
//       just that URI to the env-var form; preserve other rows.
// Tables with rows whose URIs all resolve are treated as
// user-customized and left alone.
if( destFile.FileExists() )
{
    LIBRARY_TABLE existing( destFile, LIBRARY_TABLE_SCOPE::GLOBAL );

    if( existing.IsOk() && !existing.Rows().empty() )
    {
        bool repaired = false;

        wxString stockUri = wxString::Format( wxT( "${%s}/%s" ),
                                              ENV_VAR::GetVersionedEnvVarName( wxT( "TEMPLATE_DIR" ) ),
                                              filename );

        for( LIBRARY_TABLE_ROW& row : existing.Rows() )
        {
            if( row.Type() != LIBRARY_TABLE_ROW::TABLE_TYPE_NAME )
                continue;

            if( row.Nickname() != wxT( "KiCad" ) )
                continue;

            // URI starting with ${KICAD<n>_TEMPLATE_DIR} is already
            // portable; leave it. Only repair absolute paths that
            // don't resolve.
            if( row.URI().StartsWith( wxT( "${" ) ) )
                continue;

            if( wxFileName( row.URI() ).IsFileReadable() )
                continue;

            wxLogInfo( wxT( "Repairing stale chained URI in global %s: '%s' -> '%s'" ),
                       filename, row.URI(), stockUri );
            row.SetURI( stockUri );
            repaired = true;
        }

        if( repaired )
        {
            existing.Save().map_error(
                    [&]( const LIBRARY_ERROR& aError )
                    {
                        wxLogWarning( wxT( "Failed to save repaired global %s: %s" ),
                                      filename, aError.message );
                    } );
        }
        else
        {
            wxLogTrace( traceLibraries,
                        wxT( "seedGlobalTablesFromTemplates: %s already populated, leaving alone" ),
                        destFile.GetFullPath() );
        }

        continue;
    }

    wxLogInfo( wxT( "Replacing empty/invalid global %s with bundled template" ),
               filename );
}
else
{
    wxLogInfo( wxT( "Seeding global %s from bundled template (first run)" ),
               filename );
}

