wxString PATHS::FindExternalKiCadTemplatesPath()
{
    // Platform-standard locations to probe for a co-installed KiCad. Listed
    // in priority order — newest stable channel first. Versioned dirs catch
    // installs done before our shared %appdata%/kicad/10.0 convention.
    std::vector<wxString> candidates;

#if defined( __WXMAC__ )
    candidates.push_back( wxT( "/Applications/KiCad/KiCad.app/Contents/SharedSupport/template" ) );
#elif defined( __WXMSW__ )
    candidates.push_back( wxT( "C:\\Program Files\\KiCad\\10.0\\share\\kicad\\template" ) );
    candidates.push_back( wxT( "C:\\Program Files\\KiCad\\9.0\\share\\kicad\\template" ) );
#else  // Linux
    candidates.push_back( wxT( "/usr/share/kicad/template" ) );
    candidates.push_back( wxT( "/usr/local/share/kicad/template" ) );
    candidates.push_back( wxT( "/opt/kicad/share/kicad/template" ) );
#endif

    for( const wxString& path : candidates )
    {
        if( wxFileName::DirExists( path ) )
        {
            wxLogTrace( "Paths", wxT( "Found external KiCad templates at %s" ), path );
            return wxFileName( path, wxEmptyString ).GetPathWithSep();
        }
    }

    return wxEmptyString;
}

