143	{
144	    if( auto it = std::ranges::find_if( m_providers,
145	                                        [&]( const std::unique_ptr<STARTWIZARD_PROVIDER>& aProvider )
146	                                        {
147	                                            return aProvider->Name() == aName;
148	                                        } ); it != m_providers.end() )
